def investigate(context, acquire):
    receipts = context.get('receipts') or []
    seen = set()
    for row in receipts:
        query = row.get('query') if isinstance(row, dict) else None
        if isinstance(query, dict):
            actions = query.get('actions')
            if isinstance(actions, list):
                seen.add(tuple((a.get('op'), a.get('id')) for a in actions if isinstance(a, dict)))
    actions = [
        {'op': 'put', 'id': 5},
        {'op': 'begin'},
        {'op': 'put', 'id': 9},
        {'op': 'rollback'},
        {'op': 'put', 'id': 2}
    ]
    key = tuple((a['op'], a.get('id')) for a in actions)
    if key in seen:
        return {'query': None, 'note': {'status': 'duplicate', 'chosen': key}}
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'AUTOINCREMENT sqlite_sequence is not rolled back; parent restores high=5 and predicts 6, native likely predicts 10'}}

